        .target(name: "ExtPluginWebView"),
        .target(name: "ExtWeb"),
        .target(name: "ExtWebKit", dependencies: ["ExtWeb"]),
        .target(name: "ExtClipboard"),
        .target(name: "ExtSystem"),
